const out = [];
for (const item of $input.all()) {
  const j = item.json;
  out.push({
    json: {
      title: j.title || j.subject || '',
      link: j.link || (j.links && j.links[0] && j.links[0].href) || j.url || '',
      content: j.contentSnippet || j.content || j.summary || j.description || '',
      source: j.creator || j.source || j.feedUrl || 'unknown',
      pubDate: j.pubDate || j.isoDate || j.date || new Date().toISOString()
    }
  });
}
return out;

function normTitle(t) {
  return (t || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();
}
function similarity(a, b) {
  const setA = new Set(normTitle(a).split(' '));
  const setB = new Set(normTitle(b).split(' '));
  if (setA.size === 0 || setB.size === 0) return 0;
  let overlap = 0;
  for (const w of setA) if (setB.has(w)) overlap++;
  return overlap / Math.min(setA.size, setB.size);
}

const items = $input.all();
const seenUrls = new Set();
const kept = [];

for (const item of items) {
  const url = (item.json.link || '').split('?')[0].replace(/\/$/, '');
  const title = item.json.title;

  if (url && seenUrls.has(url)) continue;

  let isDupe = false;
  for (const k of kept) {
    if (similarity(title, k.json.title) >= 0.75) { isDupe = true; break; }
  }
  if (isDupe) continue;

  if (url) seenUrls.add(url);
  kept.push(item);
}

return kept;

const out = [];
for (const item of $input.all()) {
  let parsed = {};
  try {
    const raw = item.json.message?.content || item.json.content || item.json.text || '{}';
    parsed = JSON.parse(raw);
  } catch (e) {
    parsed = { is_funding: false, confidence: 0 };
  }
  out.push({
    json: {
      ...parsed,
      source_url: item.json.link,
      source_name: item.json.source,
      pub_date: item.json.pubDate,
      original_title: item.json.title
    }
  });
}
return out;

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenUrls) staticData.seenUrls = [];

const out = [];
for (const item of $input.all()) {
  const url = item.json.source_url;
  if (staticData.seenUrls.includes(url)) continue;
  staticData.seenUrls.push(url);
  if (staticData.seenUrls.length > 2000) staticData.seenUrls.shift();
  out.push(item);
}
return out;

