const items = $input.first().json;
const list = Array.isArray(items) ? items.filter(i => i.company) : [];
const byCompany = {};
for(const j of list){
  const key = j.company;
  if(!byCompany[key]) byCompany[key] = { company: key, roles: [], url: j.url };
  byCompany[key].roles.push(j.position || j.title || 'Role');
}
return Object.values(byCompany).filter(c => c.roles.length >= 2).map(c => ({ json: { company: c.company, role_count: c.roles.length, roles: c.roles, hiring_source: 'RemoteOK', hiring_source_url: c.url } }));

const byCompany = {};
for(const item of $input.all()){
  const title = item.json.title || '';
  const parts = title.split(':');
  if(parts.length < 2) continue;
  const company = parts[0].trim();
  const role = parts.slice(1).join(':').trim();
  if(!byCompany[company]) byCompany[company] = { company, roles: [], url: item.json.link };
  byCompany[company].roles.push(role);
}
return Object.values(byCompany).filter(c => c.roles.length >= 2).map(c => ({ json: { company: c.company, role_count: c.roles.length, roles: c.roles, hiring_source: 'WeWorkRemotely', hiring_source_url: c.url } }));

