const row = $input.first().json;
const isFunded = String(row.is_funded).toLowerCase() === 'true';
const isHiring = String(row.is_hiring).toLowerCase() === 'true' && Number(row.hiring_role_count || 0) >= 2;

let tier = 'NONE';
if (isFunded && isHiring) tier = 'HOT';
else if (isFunded || isHiring) tier = 'WARM';

const lastNotifiedTier = row.last_notified_tier || 'NONE';
const tierRank = { NONE: 0, WARM: 1, HOT: 2 };
const shouldNotify = tier !== 'NONE' && tierRank[tier] > tierRank[lastNotifiedTier];

return [{ json: { ...row, tier, should_notify: shouldNotify } }];
